const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Hood Canal geometry (bounding box)
  const hoodCanal = ee.Geometry.Rectangle([-122.95, 47.65, -122.65, 47.95]);

  // Function to mask clouds in Sentinel-2
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // August 2021 collection
  const col2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(hoodCanal)
    .filterDate('2021-08-01', '2021-08-31')
    .map(maskClouds)
    .select(['B2', 'B3', 'B4', 'B8']);

  // Late August 2022 collection
  const col2022 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(hoodCanal)
    .filterDate('2022-08-15', '2022-08-31')
    .map(maskClouds)
    .select(['B2', 'B3', 'B4', 'B8']);

  const size2021 = col2021.size().getInfo();
  const size2022 = col2022.size().getInfo();

  print(`Aug 2021 Images: ${size2021}, Aug 2022 Images: ${size2022}`);

  if (size2021 === 0 || size2022 === 0) {
    print("C1: Empty Collection - No images found for one or both periods.");
    return;
  }

  // Create median composites
  const median2021 = col2021.median();
  const median2022 = col2022.median();

  // Calculate NDCI (Normalized Difference Chlorophyll Index) = (NIR - Red) / (NIR + Red)
  // Higher values suggest algae/bloom presence
  const ndci2021 = median2021.normalizedDifference(['B8', 'B4']).rename('NDCI');
  const ndci2022 = median2022.normalizedDifference(['B8', 'B4']).rename('NDCI');

  // Also track blue band (B2) as brightness indicator
  const blue2021 = median2021.select('B2');
  const blue2022 = median2022.select('B2');

  // Reduce to get statistics
  const stats2021_ndci = ndci2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hoodCanal,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2022_ndci = ndci2022.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hoodCanal,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2021_blue = blue2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hoodCanal,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2022_blue = blue2022.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hoodCanal,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  // Get pixel counts to verify valid data
  const count2021 = ndci2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hoodCanal,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const count2022 = ndci2022.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hoodCanal,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const validPixels2021 = count2021.NDCI || 0;
  const validPixels2022 = count2022.NDCI || 0;

  print(`2021 Valid Pixels: ${validPixels2021}, 2022 Valid Pixels: ${validPixels2022}`);

  if (validPixels2021 === 0 || validPixels2022 === 0) {
    print("C2: No Valid Pixels - After masking, no valid data remains.");
    return;
  }

  const ndci2021_val = stats2021_ndci.NDCI;
  const ndci2022_val = stats2022_ndci.NDCI;
  const blue2021_val = stats2021_blue.B2;
  const blue2022_val = stats2022_blue.B2;

  if (ndci2021_val === null || ndci2022_val === null || 
      blue2021_val === null || blue2022_val === null) {
    print("C3: Calculation Failure - Result is null or invalid.");
    return;
  }

  print(`NDCI 2021: ${ndci2021_val.toFixed(4)}, NDCI 2022: ${ndci2022_val.toFixed(4)}`);
  print(`Blue 2021: ${blue2021_val.toFixed(0)}, Blue 2022: ${blue2022_val.toFixed(0)}`);

  // Determine if 2022 bloom was noticeably larger
  // "Brighter blue" = higher blue band values and potentially higher NDCI (more vegetation/algae)
  const ndciIncrease = ((ndci2022_val - ndci2021_val) / Math.abs(ndci2021_val + 0.0001)) * 100;
  const blueIncrease = ((blue2022_val - blue2021_val) / blue2021_val) * 100;

  print(`NDCI % Change: ${ndciIncrease.toFixed(1)}%, Blue % Change: ${blueIncrease.toFixed(1)}%`);

  // A noticeable bloom would show higher blue brightness and higher NDCI
  // Threshold: >10% increase in either metric suggests a notable bloom
  if (blueIncrease > 10 || ndciIncrease > 15) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
